const dbToLin = (db) => Math.pow(10, db / 20);
const linToDb = (x) => 20 * Math.log10(Math.max(x, 1e-6));
const coef = (ms) => Math.exp(-1 / ((Math.max(ms, 0.05) / 1000) * sampleRate));

// 컴프레서. 두 번째 입력이 연결되어 있으면 그 소리(사이드체인 입력)를 기준으로 누른다.
class Comp extends AudioWorkletProcessor {
  static get parameterDescriptors() {
    return [
      { name: 'thr', defaultValue: -24, automationRate: 'k-rate' },
      { name: 'ratio', defaultValue: 4, automationRate: 'k-rate' },
      { name: 'att', defaultValue: 5, automationRate: 'k-rate' },
      { name: 'rel', defaultValue: 120, automationRate: 'k-rate' },
      { name: 'makeup', defaultValue: 0, automationRate: 'k-rate' },
      { name: 'key', defaultValue: 0, automationRate: 'k-rate' },
    ];
  }
  constructor() {
    super();
    this.env = 0;
  }
  process(inputs, outputs, p) {
    const inp = inputs[0], key = inputs[1], out = outputs[0];
    if (!inp.length) return true;
    // 사이드체인 입력이 지정되면, 그 트랙이 조용할 때는 누르지 않는다
    const src = p.key[0] >= 0.5 ? key || [] : inp;
    const thr = p.thr[0], ratio = p.ratio[0], mk = dbToLin(p.makeup[0]);
    const a = coef(p.att[0]), r = coef(p.rel[0]);
    const n = inp[0].length;
    for (let i = 0; i < n; i++) {
      let lv = 0;
      for (let c = 0; c < src.length; c++) lv = Math.max(lv, Math.abs(src[c][i]));
      this.env = lv > this.env ? a * this.env + (1 - a) * lv : r * this.env + (1 - r) * lv;
      const over = linToDb(this.env) - thr;
      const g = over > 0 ? dbToLin(-over * (1 - 1 / ratio)) : 1;
      for (let c = 0; c < out.length; c++) out[c][i] = (inp[c] || inp[0])[i] * g * mk;
    }
    return true;
  }
}
registerProcessor('comp', Comp);

// 게이트: 스레숄드보다 작은 소리를 닫는다.
class Gate extends AudioWorkletProcessor {
  static get parameterDescriptors() {
    return [
      { name: 'thr', defaultValue: -40, automationRate: 'k-rate' },
      { name: 'att', defaultValue: 1, automationRate: 'k-rate' },
      { name: 'rel', defaultValue: 80, automationRate: 'k-rate' },
    ];
  }
  constructor() {
    super();
    this.env = 0;
    this.g = 0;
  }
  process(inputs, outputs, p) {
    const inp = inputs[0], out = outputs[0];
    if (!inp.length) return true;
    const thr = dbToLin(p.thr[0]);
    const a = coef(p.att[0]), r = coef(p.rel[0]), ef = coef(10);
    for (let i = 0; i < inp[0].length; i++) {
      let lv = 0;
      for (let c = 0; c < inp.length; c++) lv = Math.max(lv, Math.abs(inp[c][i]));
      this.env = lv > this.env ? lv : ef * this.env + (1 - ef) * lv;
      const target = this.env > thr ? 1 : 0;
      this.g = target > this.g ? a * this.g + (1 - a) * target : r * this.g + (1 - r) * target;
      for (let c = 0; c < out.length; c++) out[c][i] = (inp[c] || inp[0])[i] * this.g;
    }
    return true;
  }
}
registerProcessor('gate', Gate);

